#!/bin/bash
IFS='.' read -r IP1 IP2 IP3 IP4 <<< "$1"; IFS='.' read -r MASK1 MASK2 MASK3 MASK4 <<< "$2"; BROADCAST1=$(((IP1 & MASK1)|(255 - MASK1))); BROADCAST2=$(((IP2 & MASK2)|(255 - MASK2))); BROADCAST3=$(((IP3 & MASK3)|(255 - MASK3))); BROADCAST4=$(((IP4 & MASK4)|(255 - MASK4))); printf "%d.%d.%d.%d\n" "$BROADCAST1" "$BROADCAST2" "$BROADCAST3" "$BROADCAST4"
